## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/scsLogic.ts`

```typescript
export type PhaseType = "trial" | "implant" | "revision";

export type SCSInput = {
  age: string; phase: string; symptomDurationMonths: string;
  painScore: string; indications: string[]; conservativeTherapies: string[];
  contraindications: string[]; trialReliefPercent: string;
  psychologicalClearance: boolean; priorTrialSuccess: boolean;
};

export type COR = "I" | "IIa" | "IIb" | "III";

export function getCORLabel(cor: COR): string {
  return { I: "Class I — Recommended", IIa: "Class IIa — Reasonable", IIb: "Class IIb — May Be Considered", III: "Class III — Not Recommended" }[cor];
}
export function getCORColor(cor: COR): string {
  return { I: "border-green-500 text-green-700", IIa: "border-blue-500 text-blue-700", IIb: "border-yellow-500 text-yellow-700", III: "border-red-500 text-red-700" }[cor];
}

export function assessSCS(input: SCSInput) {
  const symptomMonths = parseFloat(input.symptomDurationMonths) || 0;
  const painScore = parseFloat(input.painScore) || 0;
  const trialRelief = parseFloat(input.trialReliefPercent) || 0;

  const absoluteContraindications = ["active-infection", "coagulopathy", "demand-pacemaker", "psychosis", "drug-seeking", "pregnancy"];
  const hardContra = input.contraindications.filter(c => absoluteContraindications.includes(c));

  if (hardContra.length > 0) {
    return {
      recommendation: "SCS Contraindicated",
      cor: "III" as COR, loe: "C", urgency: "Contraindicated",
      rationale: ["Absolute contraindications identified — SCS cannot proceed until resolved."],
      contraindications: hardContra.map(c => ({
        "active-infection": "Active infection — must be resolved before implant",
        "coagulopathy": "Uncorrectable coagulopathy",
        "demand-pacemaker": "Demand cardiac pacemaker — absolute contraindication",
        "psychosis": "Untreated psychiatric disorder",
        "drug-seeking": "Active drug-seeking behavior",
        "pregnancy": "Pregnancy",
      }[c] || c)),
      optimizationSteps: ["Address all contraindications", "Psychiatric evaluation and treatment if needed"]
    };
  }

  const rationale: string[] = [];
  const optimizationSteps: string[] = [];
  let cor: COR = "IIb";
  let urgency = "Elective";

  const hasFBSS = input.indications.includes("fbss");
  const hasCRPS = input.indications.includes("crps");
  const hasNeuropathicPain = input.indications.includes("radiculopathy") || input.indications.includes("diabetic-neuropathy");
  const adequateConservative = input.conservativeTherapies.length >= 3;

  if (input.phase === "implant") {
    if (input.priorTrialSuccess && trialRelief >= 50 && input.psychologicalClearance) {
      cor = "I"; urgency = "Appropriate";
      rationale.push("Successful SCS trial (≥50% pain relief) with psychological clearance");
      rationale.push("Permanent implant is strongly recommended per NANS/ASIPP guidelines");
    } else if (!input.priorTrialSuccess) {
      cor = "III"; urgency = "Trial Required First";
      rationale.push("Permanent implant requires successful trial period first");
      optimizationSteps.push("Perform SCS trial before proceeding with permanent implant");
    } else if (trialRelief < 50) {
      cor = "III"; urgency = "Trial Unsuccessful";
      rationale.push("Trial relief <50% — permanent implant not recommended");
      optimizationSteps.push("Consider alternative pain management strategies");
    } else if (!input.psychologicalClearance) {
      cor = "IIb"; urgency = "Psychological Clearance Required";
      rationale.push("Psychological evaluation required before permanent implant");
      optimizationSteps.push("Complete psychological evaluation with pain psychologist");
    }
  } else if (input.phase === "trial") {
    if ((hasFBSS || hasCRPS || hasNeuropathicPain) && adequateConservative && symptomMonths >= 6 && input.psychologicalClearance) {
      cor = "I"; urgency = "Appropriate";
      rationale.push("Appropriate indication (FBSS, CRPS, or neuropathic pain) with adequate conservative therapy failure");
      rationale.push("Psychological clearance obtained");
      rationale.push("SCS trial is strongly recommended per NANS guidelines");
    } else if ((hasFBSS || hasCRPS || hasNeuropathicPain) && adequateConservative && !input.psychologicalClearance) {
      cor = "IIa"; urgency = "Psychological Clearance Needed";
      rationale.push("Appropriate indication with conservative therapy failure");
      optimizationSteps.push("Complete psychological evaluation before trial");
    } else if (!adequateConservative) {
      cor = "IIb"; urgency = "Insufficient Conservative Therapy";
      rationale.push("Insufficient conservative therapy trial — most payers require ≥6 months multimodal treatment");
      optimizationSteps.push("Continue multimodal therapy (PT, medications, injections, psychology) for ≥6 months");
    } else {
      cor = "IIb"; urgency = "Insufficient Criteria";
      rationale.push("Indication or conservative therapy criteria not fully met");
      optimizationSteps.push("Document specific indication (FBSS, CRPS, or neuropathic pain)");
    }
  } else {
    cor = "IIa"; urgency = "Reasonable";
    rationale.push("SCS revision/replacement — appropriate if prior device provided benefit");
    optimizationSteps.push("Document prior SCS benefit and reason for revision");
  }

  if (painScore >= 7) rationale.push("Severe pain (NRS ≥7) supports intervention");
  if (input.contraindications.includes("mri-dependent")) optimizationSteps.push("MRI-dependent condition — select MRI-compatible SCS device");

  return {
    recommendation: cor === "I" ? (input.phase === "implant" ? "Permanent SCS Implant Recommended" : "SCS Trial Recommended") : cor === "IIa" ? "SCS Reasonable" : cor === "III" ? "SCS Not Indicated" : "Additional Requirements Needed",
    cor, loe: (hasFBSS || hasCRPS) ? "A" : "B", urgency, rationale,
    contraindications: input.contraindications.filter(c => !absoluteContraindications.includes(c)).map(c => c),
    optimizationSteps
  };
}
